begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.credit(amount bigint default 10000, key uuid default '5b000000-0000-4000-8000-000000000001', note text default 'Fondos ficticios verificados') returns jsonb language sql as $$
 select school_wallet_replenish('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000005201',amount,key,'Prueba local',note)$$;
create function pg_temp.history(before bigint default null) returns jsonb language sql as $$select school_wallet_read('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000005201',before)$$;
select ok(not has_function_privilege('anon','school_wallet_read(uuid,uuid,bigint)','execute'),'Anonymous cannot read');
select ok(not has_function_privilege('service_role','school_wallet_replenish(uuid,uuid,bigint,uuid,text,text)','execute'),'No service financial bypass');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select is(pg_temp.history()->'wallet'->>'balance_minor','0','Existing authoritative zero balance');
select throws_ok($$select pg_temp.credit(0)$$,'22023',null,'Zero rejected');
select throws_ok($$select pg_temp.credit(-1)$$,'22023',null,'Negative rejected');
select throws_ok($$select school_wallet_replenish('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000005201',1,'5b000000-0000-4000-8000-000000000009','','')$$,'23514',null,'Verification evidence required');
select lives_ok($$select pg_temp.credit()$$,'Authorized manual verified credit');
select is(pg_temp.credit()->>'balance_after_minor','10000','Exact replay retains original resulting balance');
select throws_ok($$select pg_temp.credit(9999)$$,'23505',null,'Changed amount same key denied');
select throws_ok($$select pg_temp.credit(10000,'5b000000-0000-4000-8000-000000000001','Changed note')$$,'23505',null,'Changed evidence denied');
select is(pg_temp.history()->'wallet'->>'balance_minor','10000','One credit only');
select is(pg_temp.history()->'movements'->0->>'type','replenishment','Credit appears');
select is(pg_temp.history()->'movements'->0->>'source','manual_verified','Source preserved');
select is(pg_temp.history()->'movements'->0->>'amount_minor','10000','Positive credit direction');
select throws_ok($$select pg_temp.credit(9223372036854775807,'5b000000-0000-4000-8000-000000000002')$$,'22003',null,'Overflow rolls back');
select is(pg_temp.history()->'wallet'->>'balance_minor','10000','Overflow did not alter balance');
reset role;
select is((select count(*) from wallet_replenishments where idempotency_key='5b000000-0000-4000-8000-000000000002'),0::bigint,'Overflow left no partial source');
select throws_ok($$update wallet_ledger_entries set amount_minor=1 where wallet_id='00000000-0000-0000-0000-000000007001'$$,'23514',null,'Ledger immutable');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select throws_ok($$select pg_temp.credit()$$,'42501',null,'Cashier cannot replenish');
select throws_ok($$select pg_temp.history()$$,'42501',null,'Cashier cannot read school ledger');
select open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009501',0,'phase5b-open-local-0001');
select set_config('phase5b.sid',(select session_id::text from get_my_open_register_session()),true);
create function pg_temp.sale(key text) returns jsonb language sql as $$select checkout_purchase(jsonb_build_object('request_key',key,'register_session_id',current_setting('phase5b.sid'),'cafeteria_customer_id','00000000-0000-0000-0000-000000006901','items',jsonb_build_array(jsonb_build_object('product_id','00000000-0000-0000-0000-000000008101','quantity',1,'expected_product_version',1,'expected_unit_price_minor','5000')),'expected_total_minor','5000','tender',jsonb_build_object('type','student_wallet')))$$;
select lives_ok($$select pg_temp.sale('phase5b-wallet-sale-0001')$$,'Existing wallet purchase commits');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select is(pg_temp.history()->'wallet'->>'balance_minor','5000','Purchase debits authoritative balance');
select is(pg_temp.history()->'movements'->0->>'amount_minor','-5000','Purchase debit direction');
select is(pg_temp.history()->'movements'->0->>'type','purchase','Purchase in same ledger');
select is(pg_temp.history()->'movements'->0->>'balance_after_minor','5000','Historical resulting balance');
select is(pg_temp.history()->'movements'->0->>'receipt_number','1','Authoritative receipt reference');
select is(pg_temp.history()->'movements'->0->'items'->0->>'name','Agua mineral','Immutable purchased item');
select is(pg_temp.history(2)->'movements'->0->>'type','replenishment','Version keyset pagination');
select lives_ok($$select pg_temp.credit(1000,'5b000000-0000-4000-8000-000000000003')$$,'Stale client balance not trusted');
select is(pg_temp.history()->'wallet'->>'balance_minor','6000','Server-derived concurrent-state balance');
select is(pg_temp.credit()->>'balance_after_minor','10000','Old replay does not masquerade as current balance');
select throws_ok($$select school_wallet_read('00000000-0000-0000-0000-000000000011','99999999-0000-4000-8000-000000000001')$$,'42501',null,'Foreign student denied');
select throws_ok($$select school_wallet_read('99999999-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000005201')$$,'42501',null,'Foreign school denied');
select set_student_wallet_status('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000007001','frozen');
select throws_ok($$select pg_temp.credit(1,'5b000000-0000-4000-8000-000000000004')$$,'23514',null,'Frozen wallet not funded');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select throws_ok($$select pg_temp.sale('phase5b-frozen-sale-001')$$,'23514','WALLET_FROZEN','Frozen wallet cannot spend');
reset role;
update student_wallets set status='active' where id='00000000-0000-0000-0000-000000007001';
-- Spending capacity remains separate from stored value.
insert into student_spending_controls(account_id,school_id,student_id,currency_code,daily_limit_minor,updated_by_person_id)
values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000005201','DOP',5000,'00000000-0000-0000-0000-000000001002');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select lives_ok($$select pg_temp.credit(10000,'5b000000-0000-4000-8000-000000000005')$$,'Funding does not consume or expand daily capacity');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select throws_ok($$select pg_temp.sale('phase5b-daily-limit-001')$$,'23514','DAILY_LIMIT_EXCEEDED','Credit does not bypass existing daily spending');
reset role;update student_spending_controls set daily_limit_enabled=false,per_transaction_limit_enabled=true,per_transaction_limit_minor=4000,version=version+1 where student_id='00000000-0000-0000-0000-000000005201';
set local role authenticated;
select throws_ok($$select pg_temp.sale('phase5b-per-purchase-001')$$,'23514','TRANSACTION_LIMIT_EXCEEDED','Purchase limit preserved');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
do $$begin for n in 1..26 loop perform pg_temp.credit(1,gen_random_uuid()); end loop; end$$;
select is(jsonb_array_length(pg_temp.history()->'movements'),25,'History bounded to 25 with lookahead');
select isnt(pg_temp.history()->>'next_before',null,'Next page cursor present');
select is(jsonb_array_length(pg_temp.history((pg_temp.history()->>'next_before')::bigint)->'movements'),5,'Next page no duplicates or omissions');
reset role;
insert into persons(id,display_name) values('5b000000-0000-4000-8000-000000000100','Estudiante nuevo local');
insert into students(id,account_id,school_id,person_id,student_code,first_name,last_name,display_name) values('5b000000-0000-4000-8000-000000000101','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','5b000000-0000-4000-8000-000000000100','WALLET-LOCAL','Estudiante','nuevo local','Estudiante nuevo local');
set local role authenticated;
select throws_ok($$select school_wallet_replenish('00000000-0000-0000-0000-000000000011','5b000000-0000-4000-8000-000000000101',100,'5b000000-0000-4000-8000-000000000102','Local','Verificado')$$,'23514',null,'No wallet or credit without active enrollment');
reset role;
select is((select count(*) from student_wallets where student_id='5b000000-0000-4000-8000-000000000101'),0::bigint,'Failed initial funding creates no partial wallet');
insert into student_enrollments(account_id,school_id,student_id,starts_on) values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','5b000000-0000-4000-8000-000000000101','2026-01-01');
set local role authenticated;
select is(school_wallet_replenish('00000000-0000-0000-0000-000000000011','5b000000-0000-4000-8000-000000000101',100,'5b000000-0000-4000-8000-000000000102','Local','Verificado')->>'balance_after_minor','100','Atomic initial wallet and credit via existing creation authority');
reset role;
update school_memberships set status='suspended' where person_id='00000000-0000-0000-0000-000000001002';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select throws_ok($$select pg_temp.credit()$$,'42501',null,'Suspended authority cannot recover');
select throws_ok($$select pg_temp.history()$$,'42501',null,'Suspended authority cannot read');
reset role;
select is((select current_balance_minor::numeric from student_wallets where id='00000000-0000-0000-0000-000000007001'),(select sum(amount_minor::numeric) from wallet_ledger_entries where wallet_id='00000000-0000-0000-0000-000000007001'),'Balance equals immutable signed ledger sum');
select is((select pikas_private.register_cash_summary(current_setting('phase5b.sid')::uuid)->>'expected_minor'),'0','Credit and wallet purchase do not create register cash');
-- Frozen admin POV does not gain financial capability.
select set_config('phase5b.sandbox_school',(select school_id::text from pikas_private.sandbox_pov_personas where pov_code='school_admin' limit 1),true);
select set_config('phase5b.sandbox_student',(select id::text from students where school_id=current_setting('phase5b.sandbox_school')::uuid limit 1),true);
select set_config('request.jwt.claim.sub','ec08ad21-4020-4b0d-b041-ee4a1fe09471',true);set local role authenticated;
select platform_enter_sandbox_pov(gen_random_uuid(),'03e71159-69e9-4387-9b3b-65799d49faf0','b9496342-5079-46ae-83b8-05c39bcbd7fe','school_admin');
select throws_ok($$select school_wallet_read(current_setting('phase5b.sandbox_school')::uuid,current_setting('phase5b.sandbox_student')::uuid)$$,'42501',null,'Sandbox school POV cannot read financial ledger');
select throws_ok($$select school_wallet_replenish(current_setting('phase5b.sandbox_school')::uuid,current_setting('phase5b.sandbox_student')::uuid,1,gen_random_uuid(),'Local','Verificado')$$,'42501',null,'Sandbox school POV cannot replenish');
reset role;
set constraints all immediate;
select * from finish();
rollback;
